/**
 * Navigation as text, with an optional Button-styled variant (`design/components/link.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/link.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  agentPress,
  claimSlot,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/link.module.css'

export type LinkVariant = NonNullable<LinkProps['variant']>

export interface LinkButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'accent' | 'neutral'
  ghost: 'accent' | 'neutral'
}

export interface LinkProps {
  buttonVariant?: 'solid' | 'soft' | 'outline' | 'ghost'
  children: JSX.Element
  /**
   * Adds the glyph, the new tab, and the `rel` that makes it safe.
   */
  external?: boolean
  href: string
  /**
   * The app's router. A click the browser would follow in this tab calls it with `href` in place
   * of the browser's navigation; a click with a modifier key or another button, and a click on
   * an `external` link, stay the browser's. It routes and does nothing else: a click that
   * changes data is a Button.
   */
  onNavigate?: (href: string) => void
  /**
   * Control size, as on Button.
   */
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  /**
   * `inline` sits inside a sentence and `standalone` is a row or a title.
   */
  variant?: 'inline' | 'standalone' | 'button'
}

/** Navigation as text, with an optional Button-styled variant. */
export default function Link(given: LinkProps): JSX.Element {
  const props = mergeProps(
    {
      variant: 'inline',
      external: false,
      buttonVariant: 'soft',
      tone: 'accent',
      size: 'md',
    } as Defaults<LinkProps, 'variant' | 'external' | 'buttonVariant' | 'tone' | 'size'>,
    claimSlot(given),
  )
  return scope(() => {
    const control = elementRef<HTMLElement>()
    const navigatesHere = createDerived(
      () =>
        (event: MouseEvent): boolean =>
          !event.defaultPrevented &&
          event.button === 0 &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey,
    )
    const route = createDerived(() => (event: MouseEvent): void => {
      if (props.external || !navigatesHere.value(event)) return
      event.preventDefault()
      props.onNavigate?.(props.href)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Link',
        element: () => control.value,
        state: () => ({ external: props.external }),
        actions: {
          press: () =>
            (() => {
              if (props.external)
                throw new Error(
                  'An external link opens a new tab, which only a person’s press opens.',
                )
              agentPress(control.value)
            })(),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {props.variant === 'button' ? (
          <a
            class={styles.costume}
            href={props.href}
            data-variant={props.buttonVariant}
            data-tone={props.tone}
            data-size={props.size}
            data-external={props.external ? '' : undefined}
            target={props.external ? '_blank' : undefined}
            rel={props.external ? 'noreferrer' : undefined}
            data-member="link"
            onclick={($event: MouseEvent) => props.onNavigate !== undefined && route.value($event)}
            ref={control.attach}
          >
            {/* label */}
            <span class={styles.costumeLabel}>{props.children}</span>
            {props.external ? (
              <span class={styles.costumeGlyph}>
                <Icon name="open-external" size={props.size} />
              </span>
            ) : null}
          </a>
        ) : (
          <a
            class={styles.link}
            href={props.href}
            data-variant={props.variant}
            data-external={props.external ? '' : undefined}
            target={props.external ? '_blank' : undefined}
            rel={props.external ? 'noreferrer' : undefined}
            data-member="link"
            onclick={($event: MouseEvent) => props.onNavigate !== undefined && route.value($event)}
            ref={control.attach}
          >
            {props.children}
            {props.external ? <Icon name="open-external" size="sm" /> : null}
          </a>
        )}
      </>
    )
  })
}
